package com.vandorlabs.neoforge.gear;

import com.vandorlabs.gear.core.GearTopology;
import com.vandorlabs.redstone.ChannelList;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;

/** Typed after-image staging is read-only even for fully formed stowed Large groups. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearLegacyDestinationChecks {
    private static int checks,ticks;private static BlockPos neighborRoot;private static UUID neighborIdentity;
    private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Legacy modular destination: "+why);}
    @SubscribeEvent public static void started(net.neoforged.neoforge.event.server.ServerStartedEvent event){if(!Boolean.getBoolean("vandorlabs.legacyDestinationChecks"))return;try{
        var world=event.getServer().overworld();int index=0;
        for(boolean large:new boolean[]{false,true})for(var facing:new Direction[]{Direction.NORTH,Direction.SOUTH,Direction.EAST,Direction.WEST})for(int height=1;height<=4;height++)for(boolean deployed:new boolean[]{false,true}){
            var root=new BlockPos(28600+index%8*8,150,28600+index/8*8);index++;for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)world.getChunk(root.getX()/16+x,root.getZ()/16+z);
            var id=UUID.randomUUID();var input=new NativeGearLegacyDestination.Column(root,facing,large,height,deployed,0,ChannelList.of(7,11),id);var result=NativeGearLegacyDestination.prepare(world,List.of(input));var before=result.stream().map(cell->new com.vandorlabs.neoforge.transfer.NativeRawCell(cell.pos,world.getBlockState(cell.pos),null,1)).toList();need(NativeGearLegacyDestination.validate(world.registryAccess(),input,before,result).size()==result.size(),"world-free exact recipe accepted");var forged=new ArrayList<>(result);var first=forged.getFirst();var falseOwner=first.tile();falseOwner.putUUID("ArmOperator",UUID.randomUUID());forged.set(0,new com.vandorlabs.neoforge.transfer.NativeRawCell(first.pos,first.state,falseOwner,1024*1024));boolean refused=false;try{NativeGearLegacyDestination.validate(world.registryAccess(),input,before,forged);}catch(IllegalArgumentException expected){refused=true;}need(refused,"forged fresh operator refused without a World");need(result.size()==height+(large?4:1),"complete strut and wheel footprint");
            var ids=new HashSet<UUID>();for(var cell:result){need(world.isEmptyBlock(cell.pos)&&world.getBlockEntity(cell.pos)==null,"preparation did not publish a native owner");var staged=(NativeGearEntity)cell.stage(world,tile->tile instanceof NativeGearEntity gear&&!gear.inert(),NativeGearSnapshot::same);need(ids.add(staged.identity())&&staged.owner().equals(root),"unique tile identity and exact legacy owner-offset packing");need(staged.settings().legacyAnyChannels()&&staged.settings().channels().equals(input.channels())&&staged.settings().footFacing()==facing.get2DDataValue(),"Source-compatible input and foot orientation");if(cell.pos.equals(root)){need(staged.identity().equals(id)&&staged.assembly()!=null&&staged.assembly().kind()==GearTopology.FootKind.WHEEL&&staged.assembly().columnHeight()==height&&staged.assembly().feet().size()==(large?4:1),"fully initialized one primary assembly");need(staged.progress()==(deployed?1:0)&&staged.target()==deployed,"stopped deployed or stowed endpoint");}else need(staged.assembly()==null,"one primary only");}
        }
        neighborRoot=new BlockPos(28700,150,28700);neighborIdentity=UUID.randomUUID();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)world.getChunk(neighborRoot.getX()/16+x,neighborRoot.getZ()/16+z);
        var old=new NativeGearLegacyDestination.Column(neighborRoot,Direction.NORTH,false,1,true,0,ChannelList.of(7,11),neighborIdentity);
        // Fixture setup of ordinary empty native components; this is not a transfer or recovery proof.
        for(var cell:NativeGearLegacyDestination.prepare(world,List.of(old))){var raw=cell.tile();if(cell.pos.equals(neighborRoot)){raw.putString("LegacyOpaqueProof","retained-own-field");raw.putInt("texture_join_policy",1);}var copy=new com.vandorlabs.neoforge.transfer.NativeRawCell(cell.pos,cell.state,raw,1024*1024);var staged=copy.stage(world,tile->tile instanceof NativeGearEntity gear&&!gear.inert(),NativeGearLegacyDestination::same);world.setBlock(cell.pos,cell.state,18);world.removeBlockEntity(cell.pos);world.setBlockEntity(staged);}

    }catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][legacy-destination] FAIL "+failure);event.getServer().halt(false);}}
    @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post event){if(!Boolean.getBoolean("vandorlabs.legacyDestinationChecks")||neighborRoot==null)return;try{need(++ticks<80,"native neighbor deferred initialization");var world=event.getServer().overworld();var root=NativeGearFormation.at(world,neighborRoot);if(root==null||!root.formationReady()||!root.completeMembers())return;
        var source=root.saveWithFullMetadata(world.registryAccess());var column=new NativeGearLegacyDestination.Column(neighborRoot.east(),Direction.NORTH,false,1,true,0,ChannelList.of(7,11),UUID.randomUUID());var result=NativeGearLegacyDestination.prepare(world,List.of(column));need(result.size()==4,"fresh column and entire existing neighbor included");var before=result.stream().map(cell->{var tile=world.getBlockEntity(cell.pos);return new com.vandorlabs.neoforge.transfer.NativeRawCell(cell.pos,world.getBlockState(cell.pos),tile==null?null:tile.saveWithFullMetadata(world.registryAccess()),1024*1024);}).toList();need(NativeGearLegacyDestination.validate(world.registryAccess(),column,before,result).size()==4,"world-free complete neighbor recipe accepted");need(source.equals(root.saveWithFullMetadata(world.registryAccess())),"neighbor remains byte-exact and physically installed during preparation");var existing=result.stream().filter(cell->cell.pos.equals(neighborRoot)).findFirst().orElseThrow();need(existing.tile().getUUID("NativeGearIdentity").equals(neighborIdentity)&&existing.tile().getString("LegacyOpaqueProof").equals("retained-own-field")&&existing.tile().getInt("texture_join_policy")==1,"neighbor identity and unknown own envelope retained");var corrupted=new ArrayList<>(result);int at=corrupted.indexOf(existing);var raw=existing.tile();raw.putInt("texture_join_policy",0);corrupted.set(at,new com.vandorlabs.neoforge.transfer.NativeRawCell(existing.pos,existing.state,raw,1024*1024));boolean rejected=false;try{NativeGearLegacyDestination.validate(world.registryAccess(),column,before,corrupted);}catch(IllegalArgumentException expected){rejected=true;}need(rejected,"opaque neighbor join-named field cannot be normalized away");
        System.out.println("[vandorlabs][legacy-destination] PASS profiles=64 checks="+checks+" exactStaging/ownerOffsets/allFacings/sizes/heights/endpoints/noMutation/pureRecipe/neighborEnvelope/forgedOperator");neighborRoot=null;event.getServer().halt(false);
    }catch(Throwable failure){neighborRoot=null;failure.printStackTrace();System.out.println("[vandorlabs][legacy-destination] FAIL "+failure);event.getServer().halt(false);}}
    private NativeGearLegacyDestinationChecks(){}
}
